-- Generated by model/lib/sql/generate.mjs. Loads FC Closed IN from cells/FC Closed IN.csv in the folder of input cells. Two rows for one cell add up.
-- @csv cells/FC Closed IN.csv
INSERT INTO "FC Closed IN" SELECT coalesce(k0."Versions", fpabench_error('cells name a member Versions does not have: ' || c."Versions")), coalesce(k1."Years", fpabench_error('cells name a member Years does not have: ' || c."Years")), coalesce(k2."Months", fpabench_error('cells name a member Months does not have: ' || c."Months")), sum(c.value::DOUBLE PRECISION)
FROM csv c LEFT JOIN "dim Versions" k0 ON k0.name = c."Versions" LEFT JOIN "dim Years" k1 ON k1.name = c."Years" LEFT JOIN "dim Months" k2 ON k2.name = c."Months"
GROUP BY 1, 2, 3
ON CONFLICT ("Versions", "Years", "Months") DO UPDATE SET v = EXCLUDED.v;
ANALYZE "FC Closed IN";
